    {
      "cell_type": "code",
      "source": [
        "# GRÁFICO 1 - MÉDIA DE NOTAS POR CATEGORIA DE HORAS DE SONO\n",
        "\n",
        "import pandas as pd\n",
        "import numpy as np\n",
        "import seaborn as sns\n",
        "import matplotlib.pyplot as plt\n",
        "\n",
        "# CRIAÇÃO DAS CATEGORIAS DE HORAS DE SONO\n",
        "bins = [4, 5, 6, 7, 8, np.inf]\n",
        "labels = ['4-5 horas', '5-6 horas', '6-7 horas', '7-8 horas', '8+ horas']\n",
        "\n",
        "df['Categoria_Sono'] = pd.cut(\n",
        "    df['Horas_de_Sono'],\n",
        "    bins=bins,\n",
        "    labels=labels,\n",
        "    right=False\n",
        ")\n",
        "\n",
        "# CÁLCULO DA MÉDIA DE NOTAS POR CATEGORIA DE SONO\n",
        "media_notas = (\n",
        "    df.groupby('Categoria_Sono', observed=True)['Notas']\n",
        "    .mean()\n",
        "    .reset_index()\n",
        ")\n",
        "\n",
        "# CRIAÇÃO DO GRÁFICO\n",
        "plt.figure(figsize=(8,5))\n",
        "\n",
        "sns.barplot(\n",
        "    data=media_notas,\n",
        "    x='Categoria_Sono',\n",
        "    y='Notas',\n",
        "    hue='Categoria_Sono',\n",
        "    palette='rocket',\n",
        "    legend=False\n",
        ")\n",
        "\n",
        "# PERSONALIZAÇÃO DO GRÁFICO\n",
        "plt.title('Média de Notas por Categoria de Horas de Sono')\n",
        "plt.xlabel('Horas de Sono')\n",
        "plt.ylabel('Média de Notas')\n",
        "plt.grid(False)\n",
        "\n",
        "# AJUSTE FINAL\n",
        "plt.tight_layout()\n",
        "plt.show()"
      ],
      "metadata": {
        "id": "BkTXpNrSTDzC"
      },
      "execution_count": null,
      "outputs": []
    },
